parameters.jsCode:
// On récupère le texte généré par Gemini
let rawText = $input.first().json.text || $input.first().json.content.parts[0].text;

// On nettoie les éventuelles balises Markdown invisibles
let cleanText = rawText.replace(/```json/gi, '').replace(/```/gi, '').trim();

// On transforme le texte en données utilisables (JSON)
let parsedData = JSON.parse(cleanText);

// On retourne le résultat
return [ { json: parsedData } ];

const rawText = $json.message.text || '';
// On retire le préfixe /brand pour garder la consigne
const brandVoice = rawText.replace(/^\/brand\s*/i, '').trim();

// Sauvegarde dans le workflow static data
const staticData = $getWorkflowStaticData('global');
staticData.brandVoice = brandVoice;

return [{
  json: {
    status: 'success',
    saved_brand: brandVoice,
    chat_id: $json.message.chat.id
  }
}];

